# apply-remote-update.ps1 -- ONE-SHOT: writes the 3 files needed for
# the kiosk to self-update over the network, then rebuilds the exe + msi.
# Run from the project ROOT (same folder as main.py, build.spec,
# make-msi.bat) -- or just run apply-remote-update.bat, which cds into here
# automatically.
#
# Each base64 payload is a single-quoted literal on ONE line -- no
# cmd.exe echo/line-wrapping, no certutil (a pattern Windows Defender
# flags for real-time scanning and was intermittently locking files
# mid-write), no whitespace-stripping needed.

$ErrorActionPreference = "Stop"
Set-Location -Path $PSScriptRoot

if (-not (Test-Path "main.py")) {
    Write-Host "ERROR: main.py not found in this folder." -ForegroundColor Red
    Write-Host "Run this from the project root."
    Read-Host "Press Enter to close"
    exit 1
}

if (Test-Path "server_supervisor.py") {
    Write-Host "Backing up existing server_supervisor.py..."
    Copy-Item "server_supervisor.py" "server_supervisor.py.bak" -Force
}

$files = @{}
$files['update_checker.py'] = ''
$files['update_check_loop.py'] = ''
$files['server_supervisor.py'] = ''

foreach ($name in $files.Keys) {
    Write-Host "Writing $name ..."
    try {
        $bytes = [Convert]::FromBase64String($files[$name])
        [IO.File]::WriteAllBytes((Join-Path $PSScriptRoot $name), $bytes)
    } catch {
        Write-Host "ERROR: failed to write $name -- $_" -ForegroundColor Red
        Read-Host "Press Enter to close"
        exit 1
    }
    if (-not (Test-Path $name)) {
        Write-Host "ERROR: $name was not created." -ForegroundColor Red
        Read-Host "Press Enter to close"
        exit 1
    }
}

Write-Host ""
Write-Host "============================================================"
Write-Host "  Source files updated. Rebuilding exe + msi..."
Write-Host "============================================================"
if (Test-Path "make-msi.bat") {
    cmd /c "make-msi.bat"
} else {
    Write-Host "WARNING: make-msi.bat not found in this folder -- rebuild manually." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "============================================================"
Write-Host "  Done."
Write-Host "============================================================"
Write-Host "  Remaining steps (one-time, on the server, not this machine):"
Write-Host "    1. Run add-update-api.sh on the stocktoolsetup VPS."
Write-Host "    2. Publish: Site admin -> Releases -> upload"
Write-Host "       dist\StockToolKiosk.exe (the raw exe, not the msi) ->"
Write-Host "       enter version -> Push."
Write-Host "  From then on, every paired kiosk self-updates within 6 hours."
Write-Host "============================================================"
Read-Host "Press Enter to close"
